from itertools import groupby


def squash(s: str) -> str:
    out: list[str] = []
    for c, group in groupby(s):
        n = sum(1 for _ in group)
        esc = "\\" + c if ("0" <= c <= "9" or c == "\\") else c
        if n >= 3:
            out.append(f"{n}{esc}")
        else:
            out.append(esc * n)
    return "".join(out)
